  CONSTRAINT "products_price_check" CHECK ("price" >= 0 AND "price" <= 10000)
);

CREATE TABLE IF NOT EXISTS "order_items" (
  "id" UUID,
  "order_id" UUID NOT NULL,
  "product_id" UUID NOT NULL,
  "quantity" INTEGER NOT NULL,
  "unit_price" NUMERIC NOT NULL,
  CONSTRAINT "order_items_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "order_items_quantity_check" CHECK ("quantity" >= 1 AND "quantity" <= 50),
  CONSTRAINT "order_items_unit_price_check" CHECK ("unit_price" >= 0 AND "unit_price" <= 10000)
);

